import sqlite3

def mk():
    d = sqlite3.connect(":memory:")
    d.execute("CREATE TABLE t(v INTEGER)")
    return d

def write(leader, follower, v, sync, backlog):
    leader.execute("INSERT INTO t VALUES(?)", (v,))
    if sync:
        follower.execute("INSERT INTO t VALUES(?)", (v,))  # wait for follower before ack
    else:
        backlog.append(v)                                  # ack now, ship later

for sync in (True, False):
    leader, follower, backlog = mk(), mk(), []
    for v in (1, 2, 3):
        write(leader, follower, v, sync, backlog)
    # leader crashes right now: the follower is promoted
    lost = 3 - follower.execute("SELECT COUNT(*) FROM t").fetchone()[0]
    print("sync" if sync else "async", "-> acknowledged 3 writes, lost on failover:", lost)
# Sync: no loss (RPO 0) but each write waits for the follower.
# Async: fast acks, but unshipped writes vanish if the leader dies.

import bisect, hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16) % 2**32

def build(nodes, vnodes):
    return sorted((h("%s#%d" % (n, i)), n) for n in nodes for i in range(vnodes))

def owner(ring, key):
    i = bisect.bisect(ring, (h(key), "")) % len(ring)   # first point clockwise
    return ring[i][1]

keys = ["key%d" % i for i in range(2000)]
for vn in (1, 100):
    r3 = build(["A", "B", "C"], vn)
    r4 = build(["A", "B", "C", "D"], vn)
    moved = sum(owner(r3, k) != owner(r4, k) for k in keys)
    counts = {n: sum(owner(r4, k) == n for k in keys) for n in "ABCD"}
    print("vnodes", vn, "keys moved on adding D:", moved, "of 2000", "load:", counts)
mod_moved = sum(h(k) % 3 != h(k) % 4 for k in keys)
print("mod N keys moved:", mod_moved, "of 2000")
# Ring moves about 1/N of keys; mod N moves most. More vnodes even out the load.

import sqlite3, json
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE orders(id INTEGER PRIMARY KEY, customer TEXT);
CREATE TABLE items(order_id INTEGER, sku TEXT, qty INTEGER);
CREATE TABLE doc_orders(id INTEGER PRIMARY KEY, doc TEXT);
""")
db.execute("INSERT INTO orders VALUES(1,'ann')")
db.executemany("INSERT INTO items VALUES(1,?,?)", [("pen", 2), ("ink", 1)])
doc = {"customer": "ann", "items": [{"sku": "pen", "qty": 2}, {"sku": "ink", "qty": 1}]}
db.execute("INSERT INTO doc_orders VALUES(1, ?)", (json.dumps(doc),))

# Relational: join to rebuild the order; easy to ask "total qty per sku" across orders
print("relational:", db.execute("SELECT o.customer, i.sku, i.qty FROM orders o "
                                "JOIN items i ON i.order_id=o.id").fetchall())
# Document: one read returns the whole aggregate
print("document  :", json.loads(db.execute("SELECT doc FROM doc_orders WHERE id=1").fetchone()[0]))
# Cross-order reporting on documents means parsing every document
tot = {}
for (d,) in db.execute("SELECT doc FROM doc_orders"):
    for it in json.loads(d)["items"]:
        tot[it["sku"]] = tot.get(it["sku"], 0) + it["qty"]
print("qty per sku from documents:", tot)

# Three replicas of one value; the network splits {A} from {B, C}.
class Node:
    def __init__(self): self.val, self.ver = "v1", 1
nodes = {"A": Node(), "B": Node(), "C": Node()}
partition = [{"A"}, {"B", "C"}]

def reach(client_side):
    return [n for n in nodes if n in client_side]

def write(side, val, ver, need):
    up = reach(side)
    if len(up) < need:
        return "REFUSED (CP: not enough nodes)"
    for n in up: nodes[n].val, nodes[n].ver = val, ver
    return "ok on " + str(up)

def read(side, need):
    up = reach(side)
    if len(up) < need:
        return "REFUSED"
    return max((nodes[n].ver, nodes[n].val) for n in up)[1]

print("majority side write (needs 2):", write(partition[1], "v2", 2, 2))
print("minority side write (needs 2):", write(partition[0], "v3", 3, 2))
print("minority CP read   (needs 2):", read(partition[0], 2))
print("minority AP read   (needs 1):", read(partition[0], 1), "<- stale but available")
print("majority read      (needs 2):", read(partition[1], 2))
# During the partition: refuse (consistent) or answer stale (available), never both.
